import{_ as o,o as t,c as n,al as a}from"./chunks/framework.CAAkqCQG.js";const p=JSON.parse('{"title":"Changelog","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://lognal.cdget.com/changelog"}],["link",{"rel":"alternate","hreflang":"en","href":"https://lognal.cdget.com/changelog"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://lognal.cdget.com/ko/changelog"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://lognal.cdget.com/changelog"}],["meta",{"property":"og:title","content":"Changelog | lognal"}],["meta",{"property":"og:description","content":"A terminal-style log viewer for the browser, drawn on a canvas. Mirror the console, read log files, and inspect typed values that expand and collapse."}],["meta",{"property":"og:url","content":"https://lognal.cdget.com/changelog"}],["meta",{"property":"og:locale","content":"en_US"}],["meta",{"name":"twitter:title","content":"Changelog | lognal"}],["meta",{"name":"twitter:description","content":"A terminal-style log viewer for the browser, drawn on a canvas. Mirror the console, read log files, and inspect typed values that expand and collapse."}]]},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md","lastUpdated":null}'),c={name:"changelog.md"};function d(l,e,s,r,i,h){return t(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p>Changes to <code>lognal</code> that affect its users, newest first.</p><h2 id="vnext-2026" tabindex="-1">vNext (2026--) <a class="header-anchor" href="#vnext-2026" aria-label="Permalink to &quot;vNext (2026--)&quot;">​</a></h2><h3 id="breaking-changes" tabindex="-1">Breaking changes <a class="header-anchor" href="#breaking-changes" aria-label="Permalink to &quot;Breaking changes&quot;">​</a></h3><ul><li><code>ViewerLabels</code> has twenty-two new labels: <code>entryActions</code>, <code>copyEntry</code>, <code>copyEntryWithTime</code>, <code>copyEntryFormatted</code>, <code>copyEntryData</code>, <code>expandAll</code>, <code>collapseAll</code>, <code>search</code>, <code>searchPrevious</code>, <code>searchNext</code>, <code>searchClose</code>, <code>searchCase</code>, <code>searchRegex</code>, <code>searchInvalid</code>, <code>searchResults</code>, <code>openLink</code>, <code>linkDialogTitle</code>, <code>linkDialogMessage</code>, <code>linkDialogOpen</code>, <code>linkDialogCancel</code>, <code>selectEntries</code> and <code>selectedEntries</code>. A complete <code>ViewerLabels</code> object of your own needs all of them. Overrides passed in <code>labels</code> are not affected.</li><li><code>RenderTheme</code> has the new colors <code>hover</code>, <code>searchMatch</code>, <code>searchCurrent</code>, <code>link</code>, <code>entrySelection</code> and <code>focusRing</code>, and <code>RowDecoration</code> the new fields <code>hovered</code>, <code>searchMatches</code>, <code>searchCurrent</code>, <code>entrySelected</code> and <code>entryFocused</code>. A <code>RenderTheme</code> object built by hand needs the six colors; spreading <code>DEFAULT_RENDER_THEME</code> covers them.</li><li><code>ToolbarOptions</code> has the new key <code>selectionMode</code>, and the toolbar shows its button by default. A complete <code>ToolbarOptions</code> object of your own needs the key.</li><li><code>LineAction</code> has a new type, <code>{ type: &#39;open-link&#39;; url: string }</code>, on the spans of links. Code that handles every type of action, such as a custom renderer, needs to handle it too.</li><li>The level menu in the toolbar is a <code>&lt;button class=&quot;lognal-levels&quot;&gt;</code> that opens a list box, instead of a <code>&lt;select&gt;</code>. Styles or tests written for the <code>&lt;select&gt;</code> need to target the button and its menu.</li></ul><h3 id="changes" tabindex="-1">Changes <a class="header-anchor" href="#changes" aria-label="Permalink to &quot;Changes&quot;">​</a></h3><ul><li>The level menu follows the theme of the viewer. The arrow keys, Home and End move through the levels, Enter or Space chooses one, and Escape closes it.</li><li>The entry under the pointer gets a light background, set with <code>--lognal-hover</code>, and a button that opens a menu of actions for it. <strong>Copy as text</strong> copies the whole entry as plain text, with every captured value written out in full on one line, even when the value is closed, and <strong>Copy with timestamp</strong> puts the time of the entry in front. <strong>Copy as formatted text</strong> breaks long values over indented lines and adds HTML with the colors of the theme for rich text, and <strong>Copy as data</strong> copies the values as JSON. A long press opens the menu on a touch screen, and Shift+F10 or the context menu key opens it from the keyboard.</li><li><code>entryMenu</code> takes <code>false</code> to turn the menu off, or an object whose <code>items</code> function adds items of your own after the built-in ones. <code>getEntryText</code> and <code>copyEntry</code> do the same from code, with <code>format: &#39;text&#39; | &#39;formatted&#39; | &#39;data&#39;</code> and <code>timestamp: true</code>.</li><li><strong>Expand all</strong> and <strong>Collapse all</strong> in the entry menu open or close every value of an entry at once, and so do <code>expandEntry</code> and <code>collapseEntry</code>.</li><li>Ctrl+F or Cmd+F, while focus is in the viewer, opens a search bar over the log. Unlike the filter, it hides nothing: every match is highlighted, the current one more strongly, and Enter, F3 or Ctrl+G move between matches. Toggles, also on Alt+C and Alt+R, make the search match letter case or read the text as a regular expression. <code>openSearch</code>, with <code>caseSensitive</code> and <code>regex</code>, <code>closeSearch</code>, <code>findNext</code> and <code>findPrevious</code> do the same from code, <code>search: false</code> turns it off, and <code>--lognal-search-match</code> and <code>--lognal-search-current</code> color it.</li><li>The log area, the input line and the filter field no longer draw a focus outline.</li><li><code>--lognal-popup-shadow</code> sets the shadow of the level menu and the entry menu.</li><li>Enter at the end of Korean text in the input line submits the command with one press. Before, the first press added a line and the second one submitted. Enter that confirms a Japanese or Chinese candidate still does not submit.</li><li>A tap on a value or a group header on a touch screen opens or closes it, as a click does. Before, a tap did nothing.</li><li><code>http</code> and <code>https</code> addresses in the log are drawn as links in <code>--lognal-link</code> and open in a new tab. <code>linkClick</code> decides what a click or a tap does: <code>&#39;confirm&#39;</code>, the default, shows the address in a dialog and asks first, <code>&#39;open&#39;</code> opens the link right away, and <code>&#39;ignore&#39;</code> only draws it. <code>core: { links: false }</code> draws addresses as plain text. The entry menu lists the links of an entry, so they also open from the keyboard, and <code>findLinks</code> finds the addresses in a string.</li><li>A click with Shift, Ctrl, Alt or Cmd held on a value, a group header or a link selects text instead of opening it. The exception is Ctrl+click, or Cmd+click on macOS, on a link in text mode: it opens the link right away, without the dialog, unless <code>linkClick</code> is <code>&#39;ignore&#39;</code>.</li><li><code>selectionMode: &#39;entry&#39;</code> selects whole entries the way a file manager selects files. A click selects an entry, Ctrl or Cmd adds or removes one, Shift selects a range, and a drag selects the entries it passes over. The arrow keys, Home, End, Page Up and Page Down move from entry to entry and outline the entry in <code>--lognal-focus-ring</code>, Space selects the entry the keyboard is on, and Ctrl+A, Ctrl+C and Escape select every entry, copy the selection and clear it. A right click, Shift+F10 or the context menu key opens a menu that copies the selected entries in the formats of the entry menu, or opens and closes their values. The <strong>Select whole entries</strong> button in the toolbar switches modes, <code>--lognal-entry-selection</code> colors the selected entries, and the status bar counts them.</li><li><code>getSelectionText</code> and <code>copySelection</code> take the options of <code>getEntryText</code> in entry mode, and <code>getSelectedEntryIds</code> returns the ids of the selected entries.</li></ul><h2 id="_0-1-0-2026-09-13" tabindex="-1">0.1.0 (2026-09-13) <a class="header-anchor" href="#_0-1-0-2026-09-13" aria-label="Permalink to &quot;0.1.0 (2026-09-13)&quot;">​</a></h2><p>The first release.</p><ul><li><code>LogViewer</code> shows logs drawn on a canvas, with a toolbar (follow new logs, clear, scroll to top and bottom, line wrapping, text filter, level filter), a status bar, timestamps and an optional input line for commands.</li><li><code>hookConsole</code> and <code>createConsole</code> record console calls. Arguments are captured when the method is called, and format specifiers, counters, timers, groups and <code>console.table</code> follow the Console Standard.</li><li>Logged objects, arrays, maps, sets, errors and DOM elements expand and collapse. Getters are never run while a value is captured.</li><li>Text written with <code>wrap: false</code>, and the output of <code>console.table</code>, keeps its lines on one row. When such a line is wider than the viewer, the log scrolls sideways.</li><li>A large log lays out the rows on screen first and the rest in small steps between frames, so changing the width does not stall the page. While the view is not following, the entry at its top stays in place when rows above it change height.</li><li><code>readTextFile</code> reads a text file in chunks and detects UTF-8, UTF-16 and the legacy encoding of the browser language, such as EUC-KR. <code>followTextFile</code> keeps reading a growing file in Chromium-based browsers.</li><li>Korean, Chinese, Japanese and emoji take two cells, Korean text wraps at spaces, and Enter in the input line waits for IME composition to finish.</li><li>Light, dark and automatic themes come from <code>--lognal-*</code> CSS custom properties in <code>lognal/style.css</code>.</li><li><code>lognal/react</code> provides a <code>LogViewer</code> React component.</li></ul>',10)])])}const u=o(c,[["render",d]]);export{p as __pageData,u as default};
